using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UdonSharpEditor;
namespace KominkaHillside.Editor {
public static partial class KH_ParadePurchasedAssets {
 const string Selection="Assets/KominkaHillside/Data/HalloweenParade/IKA2022Selection.json";
 static bool Selected=>File.Exists(Selection);
 static Mesh Load(string name){var m=AssetDatabase.LoadAssetAtPath<Mesh>(Output+"/"+name+".asset");if(m==null)throw new Exception("Prepare IKA meshes first: "+name);return m;}
 static Mesh SaveMesh(string name,Mesh mesh){mesh.name=name;var path=Output+"/"+name+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old==null){AssetDatabase.CreateAsset(mesh,path);return mesh;}EditorUtility.CopySerialized(mesh,old);old.UploadMeshData(false);UnityEngine.Object.DestroyImmediate(mesh);EditorUtility.SetDirty(old);return old;}
 static GameObject SourcePrefab(string name){var p=AssetDatabase.LoadAssetAtPath<GameObject>(Source+name+".prefab");if(p==null)throw new Exception("Missing source: "+name);return p;}
 static Material[] SourceMaterials(string name)=>SourcePrefab(name).GetComponent<MeshRenderer>().sharedMaterials;
 static Mesh Normalized(string name,float width,float height,bool centered,bool rotate){var p=SourcePrefab(name);var f=p.GetComponent<MeshFilter>();var m=UnityEngine.Object.Instantiate(f.sharedMesh);var b=m.bounds;float scale=height>0?height/b.size.y:width/b.size.x;var origin=centered?b.center:new Vector3(b.center.x,b.min.y,b.center.z);var rotation=rotate?Quaternion.Euler(0,180,0):Quaternion.identity;var v=m.vertices;var n=m.normals;var tan=m.tangents;for(int i=0;i<v.Length;i++){v[i]=rotation*((v[i]-origin)*scale);if(n.Length==v.Length)n[i]=rotation*n[i];if(tan.Length==v.Length){var t=rotation*(Vector3)tan[i];tan[i]=new Vector4(t.x,t.y,t.z,tan[i].w);}}m.vertices=v;m.normals=n;m.tangents=tan;m.colors32=Enumerable.Repeat(new Color32(255,255,255,255),m.vertexCount).ToArray();m.RecalculateBounds();return m;}
 static void Prepare(){Directory.CreateDirectory(Output);AssetDatabase.Refresh();
 SaveMesh("Hat",Normalized("Hat-shaped shelves",1.4f,0,false,false));
 var bat=Normalized("Bat",.8f,0,true,false);var bw=new BoneWeight[bat.vertexCount];var bv=bat.vertices;for(int i=0;i<bw.Length;i++){float w=Mathf.SmoothStep(0,1,Mathf.InverseLerp(.045f,.13f,Mathf.Abs(bv[i].x)));bw[i]=new BoneWeight{boneIndex0=0,weight0=1-w,boneIndex1=bv[i].x<0?1:2,weight1=w};}bat.boneWeights=bw;bat.bindposes=new[]{Matrix4x4.identity,Matrix4x4.Translate(new Vector3(.065f,0,0)),Matrix4x4.Translate(new Vector3(-.065f,0,0))};SaveMesh("Bat",bat);
 foreach(var name in new[]{"Halloween Outside Lamp_02","Halloween Outside Lamp_03"}){var lamp=Normalized(name,0,1.72f,false,false);var weights=new BoneWeight[lamp.vertexCount];var v=lamp.vertices;for(int i=0;i<v.Length;i++){float w=Mathf.SmoothStep(0,1,Mathf.InverseLerp(1.08f,1.32f,v[i].y));weights[i]=new BoneWeight{boneIndex0=0,weight0=1-w,boneIndex1=1,weight1=w};}lamp.boneWeights=weights;lamp.bindposes=new[]{Matrix4x4.identity,Matrix4x4.Translate(new Vector3(-.04f,-1.12f,0))};SaveMesh(name.EndsWith("02")?"LampL":"LampR",lamp);}
 var pumpkin=SourcePrefab("Ornamental Pumpkin_02");var filters=pumpkin.GetComponentsInChildren<MeshFilter>(true);var bounds=filters[0].sharedMesh.bounds;float size=bounds.size.x;var matrix=Matrix4x4.TRS(Vector3.zero,Quaternion.Euler(0,180,0),Vector3.one/size)*Matrix4x4.Translate(-bounds.center);var combines=new List<CombineInstance>();foreach(var f in filters)for(int i=0;i<f.sharedMesh.subMeshCount;i++)combines.Add(new CombineInstance{mesh=f.sharedMesh,subMeshIndex=i,transform=matrix*pumpkin.transform.worldToLocalMatrix*f.transform.localToWorldMatrix});var merged=new Mesh();merged.CombineMeshes(combines.ToArray(),true,true);merged.colors32=Enumerable.Repeat(new Color32(255,255,255,255),merged.vertexCount).ToArray();SaveMesh("Pumpkin",merged);
 var mat=AssetDatabase.LoadAssetAtPath<Material>(Output+"/Pumpkin.mat");if(mat==null){mat=new Material(Shader.Find("KominkaHillside/Halloween Story Prop"));AssetDatabase.CreateAsset(mat,Output+"/Pumpkin.mat");}mat.mainTexture=SourceMaterials("Ornamental Pumpkin_02")[0].mainTexture;mat.color=Color.white;EditorUtility.SetDirty(mat);AssetDatabase.SaveAssets();
 }
 static void RemoveGeometry(Transform t){var r=t.GetComponent<Renderer>();if(r!=null)UnityEngine.Object.DestroyImmediate(r);var f=t.GetComponent<MeshFilter>();if(f!=null)UnityEngine.Object.DestroyImmediate(f);}
 public static void ApplyCast(Transform root){if(!Selected)return;
 foreach(Transform a in root){if(a.name.StartsWith("Tree"))continue;var pose=a.Find("Pose");var body=pose.Find("Body");RemoveGeometry(body);
 if(a.name.StartsWith("Hat")){body.gameObject.AddComponent<MeshFilter>().sharedMesh=Load("Hat");var r=body.gameObject.AddComponent<MeshRenderer>();r.sharedMaterials=SourceMaterials("Hat-shaped shelves");r.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;r.receiveShadows=false;continue;}
 bool bat=a.name.StartsWith("Bat");var bones=bat?new[]{body,pose.Find("WingL"),pose.Find("WingR")}:new[]{body,pose.Find("Head")};foreach(var b in bones.Skip(1))RemoveGeometry(b);
 var sm=body.gameObject.AddComponent<SkinnedMeshRenderer>();sm.sharedMesh=Load(bat?"Bat":a.name);sm.bones=bones;sm.rootBone=pose;sm.sharedMaterials=SourceMaterials(bat?"Bat":a.name=="LampL"?"Halloween Outside Lamp_02":"Halloween Outside Lamp_03");sm.quality=SkinQuality.Bone2;sm.updateWhenOffscreen=true;sm.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;sm.receiveShadows=false;sm.localBounds=new Bounds(new Vector3(0,bat?0:.8f,0),bat?Vector3.one*1.4f:new Vector3(2.2f,2.8f,2.2f));
 }
 ApplyLanternCast(root);
 }
 public static void ApplyPumpkins(Transform stage){if(!Selected)return;int count=0;foreach(var ps in stage.GetComponentsInChildren<ParticleSystem>(true)){if(!ps.emission.enabled)continue;string n=ps.transform.parent.name;if(!n.Contains("guide-journey")&&!n.Contains("__lantern-"))continue;var r=ps.GetComponent<ParticleSystemRenderer>();r.mesh=Load("Pumpkin");r.sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>(Output+"/Pumpkin.mat");var main=ps.main;main.startColor=Color.white;count++;}if(count!=7)throw new Exception("Expected seven pumpkins, found "+count);}
 static void Preflight(Transform root,KH_HalloweenParadePlayback p){
 foreach(var name in new[]{"Hat-shaped shelves","Bat","Halloween Outside Lamp_02","Halloween Outside Lamp_03","Ornamental Pumpkin_02"}){var prefab=SourcePrefab(name);foreach(var f in prefab.GetComponentsInChildren<MeshFilter>(true))if(f.sharedMesh==null||f.sharedMesh.vertexCount==0||f.sharedMesh.uv.Length!=f.sharedMesh.vertexCount)throw new Exception("Invalid source mesh "+name);foreach(var r in prefab.GetComponentsInChildren<Renderer>(true))if(r.sharedMaterials.Any(m=>m==null||m.mainTexture==null||!m.shader.isSupported))throw new Exception("Invalid source material "+name);}
 foreach(Transform a in root){if(a.name.StartsWith("Tree"))continue;var pose=a.Find("Pose");if(pose==null||pose.Find("Body")==null)throw new Exception("Missing body "+a.name);var body=pose.Find("Body");if(body.localPosition!=Vector3.zero||body.localRotation!=Quaternion.identity||body.localScale!=Vector3.one)throw new Exception("Unexpected body bind transform "+a.name);foreach(var part in a.name.StartsWith("Bat")?new[]{"WingL","WingR"}:a.name.StartsWith("Lamp")?new[]{"Head"}:new string[0])if(pose.Find(part)==null)throw new Exception("Missing joint "+a.name+"/"+part);}
 if(p.effects.Count(s=>s!=null&&(s.transform.parent.name.Contains("guide-journey")||s.transform.parent.name.Contains("__lantern-")))!=7)throw new Exception("Seven source PS required");var ui=UnityEngine.Object.FindObjectOfType<KH_HalloweenParadePanel>();if(ui==null||ui.buttonLabels==null||ui.buttonWords==null||ui.buttonLabels.Length!=ui.buttonWords.Length)throw new Exception("UI arrays missing");
 }
 static void RemoveResume(){var ui=UnityEngine.Object.FindObjectOfType<KH_HalloweenParadePanel>();var old=ui.resumeSurface;var labels=new List<TMPro.TextMeshProUGUI>();var words=new List<int>();for(int i=0;i<ui.buttonLabels.Length;i++)if(ui.buttonLabels[i]!=null&&(old==null||!ui.buttonLabels[i].transform.IsChildOf(old.transform))){labels.Add(ui.buttonLabels[i]);words.Add(ui.buttonWords[i]);}ui.buttonLabels=labels.ToArray();ui.buttonWords=words.ToArray();ui.resumeSurface=null;if(old!=null)UnityEngine.Object.DestroyImmediate(old);ui._Close();UdonSharpEditorUtility.CopyProxyToUdon(ui);EditorUtility.SetDirty(ui);EditorUtility.SetDirty(UdonSharpEditorUtility.GetBackingUdonBehaviour(ui));}
 [MenuItem("Tools/KominkaHillside/Parade/41 - Apply IKA Assets")]
 public static void Apply(){Guard();var p=UnityEngine.Object.FindObjectOfType<KH_HalloweenParadePlayback>();var root=p.stageRoot.transform.Find("StoryCast");if(root==null||root.childCount!=18)throw new Exception("18 actor cast required");Preflight(root,p);Prepare();foreach(string n in new[]{"Hat","Bat","LampL","LampR","Pumpkin"})Load(n);File.WriteAllText(Selection,"{\"enabled\":true,\"source\":\"IKA Halloween Decoration_2022\",\"date\":\"2026-10-15\"}\n");ApplyCast(root);ApplyPumpkins(p.stageRoot.transform);ApplyLanternFinish(p);RemoveResume();EditorSceneManager.MarkSceneDirty(p.gameObject.scene);AssetDatabase.SaveAssets();File.WriteAllText(Evidence+"/apply.txt",DateTime.UtcNow.ToString("o")+"\nApplied Hat x2, Bat x12, Outside Lamp02/03 x1 each, pumpkin x7. Source assets untouched. Resume UI removed.\n");Debug.Log("IKA_APPLIED");}
 [MenuItem("Tools/KominkaHillside/Parade/42 - Verify IKA Assets")]
 public static void Verify(){var errors=new List<string>();var p=UnityEngine.Object.FindObjectOfType<KH_HalloweenParadePlayback>();var ui=UnityEngine.Object.FindObjectOfType<KH_HalloweenParadePanel>();if(ui.resumeSurface!=null||ui.transform.Find("ResumeAnswer")!=null)errors.Add("resume exists");object actual;var back=UdonSharpEditorUtility.GetBackingUdonBehaviour(ui);if(back.publicVariables.TryGetVariableValue("resumeSurface",out actual)&&actual is UnityEngine.Object o&&o!=null)errors.Add("backing resume exists");if(ui.buttonLabels.Any(l=>l==null)||ui.buttonLabels.Length!=ui.buttonWords.Length)errors.Add("label arrays");
 var root=p.stageRoot.transform.Find("StoryCast");if(root.GetComponentsInChildren<MeshFilter>(true).Count(f=>f.name=="Body"&&f.sharedMesh==Load("Hat"))!=2)errors.Add("two purchased hats required");var skins=root.GetComponentsInChildren<SkinnedMeshRenderer>(true);if(skins.Length!=(LanternSelected?28:14))errors.Add("skinned companions count");foreach(var r in skins){if(r.sharedMesh==null||r.bones.Any(b=>b==null)||r.sharedMesh.boneWeights.Length!=r.sharedMesh.vertexCount||r.sharedMaterials.Any(m=>m==null||m.mainTexture==null||!m.shader.isSupported))errors.Add("skin "+r.name);}
 int pumpkinCount=p.effects.Count(ps=>ps.GetComponent<ParticleSystemRenderer>().mesh==Load("Pumpkin")||(File.Exists(LanternMarker)&&ps.GetComponent<ParticleSystemRenderer>().mesh==Load("LeaderPumpkin")));if(pumpkinCount!=7)errors.Add("seven pumpkin renderers required");foreach(var r in root.GetComponentsInChildren<Renderer>(true))if(r.sharedMaterials.Any(m=>m==null||!m.shader.isSupported))errors.Add("material "+r.name);if(root.GetComponentsInChildren<Collider>(true).Length!=0)errors.Add("cast collider");
 var descriptor=UnityEngine.Object.FindObjectOfType<VRC.SDK3.Components.VRCSceneDescriptor>();if(descriptor.NetworkIDCollection.Any(n=>n.gameObject==null))errors.Add("NetworkID null object");File.WriteAllText(Evidence+"/verify.txt",DateTime.UtcNow.ToString("o")+"\n"+(errors.Count==0?"PASS: 14 skinned companions, 2 purchased hats, 7 pumpkin meshes, materials/shaders/bones, no resume proxy/backing/object; no cast colliders. Edit structure only.":string.Join("\n",errors)));if(errors.Count>0)throw new Exception(string.Join(";",errors));Debug.Log("IKA_VERIFIED");}
}
}
